/* Better Education: actual API-backed UI; no client-side grades, fake auth or invented quiz scores. */
const root=document.querySelector('#app'), overlay=document.querySelector('#overlay'), toastBox=document.querySelector('#toast');
const state={user:null,page:'dashboard',courseId:null,quiz:null,quizIndex:0,answers:[],result:null,selectedStudent:null,demo:true,chat:[{role:'bot',text:'Сәлем! Я Бебешка — твой учебный помощник. Спроси про Python, математику, физику, английский или алгоритмы. 😊'}],loading:false};
const H=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const F=s=>{try{return new Date(s).toLocaleString(state.user?.locale==='en'?'en-US':'ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}catch{return s}};
const I=(name,size=21)=>{const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M4 5.5C4 4.1 5 3 6.5 3H20v17H6.5C5 20 4 21 4 22zM4 6c1.5-1 3.5-1 5 0"/>',check:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 12 3 3 5-6"/>',brain:'<path d="M12 18c-1 0-2.2 1-2.2 2.5 0 1-2.6 1-3-.5C3 20 2 17 4 15c-2.5-1.8-1.5-5 1-6-1-3 2-6 5-5 2-3 6-2 7 1 3-.6 5 2 4 5 3 2 2 5-1 6 .5 3-2 5-5 4"/><path d="M12 7v10m-5-6h4"/>',chart:'<path d="M3 19h18M5 15l5-5 4 3 6-7"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-1 9 5-3 5 3-1-9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',logout:'<path d="M10 4H4v16h6M14 8l4 4-4 4M7 12h11"/>',users:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M17 4a4 4 0 0 1 0 8m0 3a7 7 0 0 1 5 6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',back:'<path d="m14 5-7 7 7 7"/>',send:'<path d="m3 21 18-9L3 3l4 9-4 9zm4-9h14"/>'};return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.star}</svg>`};
async function api(path,method='GET',body){const res=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-BE-Request':'1'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await res.json()}catch{data={detail:'Ошибка сервера'}}if(!res.ok){if(res.status===401 && state.user){state.user=null;renderLogin()}throw Error(typeof data.detail==='string'?data.detail:'Ошибка запроса ('+res.status+')')}return data}
function toast(text,fail=false){toastBox.textContent=text;toastBox.className='toast show'+(fail?' error':'');clearTimeout(toastBox._timer);toastBox._timer=setTimeout(()=>toastBox.className='toast',3500)}
function modal(html){overlay.className='open';overlay.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h3>Better Education</h3><button class="icon-button" data-action="close">${I('close')}</button></div>${html}</div>`}
function closeModal(){overlay.className='';overlay.innerHTML=''}
const labels={dashboard:'Главная',subjects:'Предметы',quizzes:'Тесты',assistant:'Бебешка',progress:'Прогресс',rewards:'Награды',schedule:'Расписание',assignments:'Задания',grades:'Оценки',notifications:'Уведомления',settings:'Настройки',gradebook:'Журнал',work:'Проверка работ',administration:'Управление'};
const names={kk:{dashboard:'Басты бет',subjects:'Пәндер',quizzes:'Тесттер',assistant:'Бебешка',progress:'Прогресс',rewards:'Марапаттар',schedule:'Кесте',assignments:'Тапсырмалар',grades:'Бағалар',notifications:'Хабарламалар',settings:'Баптаулар',gradebook:'Журнал',work:'Жұмыстар',administration:'Басқару'},en:{dashboard:'Home',subjects:'Subjects',quizzes:'Quizzes',assistant:'Bebeshka',progress:'Progress',rewards:'Rewards',schedule:'Schedule',assignments:'Assignments',grades:'Grades',notifications:'Notifications',settings:'Settings',gradebook:'Gradebook',work:'Submissions',administration:'Administration'}};
const tr=k=>names[state.user?.locale]?.[k]||labels[k]||k;
const ICONS={dashboard:'home',subjects:'book',quizzes:'check',assistant:'brain',progress:'chart',rewards:'award',schedule:'calendar',assignments:'check',grades:'chart',notifications:'bell',settings:'settings',gradebook:'book',work:'check',administration:'users'};
function menuItems(){return state.user.role==='student'?['dashboard','subjects','quizzes','assistant','progress','grades','assignments','rewards','schedule','notifications','settings']:state.user.role==='teacher'?['dashboard','subjects','gradebook','work','schedule','quizzes','notifications','settings']:state.user.role==='admin'?['dashboard','administration','subjects','quizzes','gradebook','work','schedule','notifications','settings']:['dashboard','grades','progress','notifications','settings']}
function shell(){document.body.dataset.theme=state.user.theme||'sky';const menus=menuItems();root.innerHTML=`<div class="app-layout"><aside class="sidebar"><div class="logo">be</div><nav class="nav" aria-label="Навигация">${menus.map(p=>`<button data-page="${p}" class="${state.page===p?'active':''}" title="${tr(p)}">${I(ICONS[p])}<span>${tr(p)}</span></button>`).join('')}</nav><div class="spacer"></div><button class="icon-button" title="Выйти" data-action="logout">${I('logout')}</button></aside><div class="page"><header class="topbar"><div><div class="eyebrow">${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><h1>${state.page==='dashboard'?'Hi, '+H(state.user.name)+' 👋':tr(state.page)}</h1></div><div class="top-actions"><button class="icon-button" title="Уведомления" data-page="notifications">${I('bell')}</button><button class="icon-button" title="Настройки" data-page="settings">${I('settings')}</button><div class="avatar">${H(state.user.name.slice(0,2).toUpperCase())}</div></div></header><main id="content"><div class="card" style="text-align:center;padding:55px">Загрузка…</div></main></div><div class="bottom-nav">${menus.filter(p=>['dashboard','subjects','quizzes','assistant','grades','gradebook','settings'].includes(p)).slice(0,4).map(p=>`<button data-page="${p}" class="${p===state.page?'active':''}">${I(ICONS[p])}<span>${tr(p)}</span></button>`).join('')}<button data-action="mobile-menu">${I('menu')}<span>Ещё</span></button></div></div>`}
function setPage(html){document.querySelector('#content').innerHTML=html}
function go(page){state.page=page;state.courseId=null;state.quiz=null;state.result=null;shell();loadPage().catch(err=>{setPage(`<div class="card"><h2>Не удалось загрузить раздел</h2><p>${H(err.message)}</p><button class="button primary" data-action="retry">Попробовать снова</button></div>`);toast(err.message,true)});window.scrollTo({top:0,behavior:'instant'})}
async function start(){try{const health=await fetch('/health').then(r=>r.json());state.demo=health.mode==='demo'}catch{root.innerHTML='<div class="boot">Сервер недоступен. Запусти Better Education через Python или Docker.</div>';return}try{state.user=await api('/me');go('dashboard')}catch{renderLogin()}}
function renderLogin(){document.body.dataset.theme='sky';root.innerHTML=`<div class="auth-layout"><div class="auth-left"><div style="position:relative;z-index:2"><div class="logo">be</div><h1 style="font-size:42px;margin-top:35px">Learn better.<br>Grow together.</h1><p class="muted" style="max-width:390px">Оценки, задания, тесты и учебный помощник — всё в одном пространстве.</p><img src="/static/bebeshka.svg" alt="Бебешка — барашек-помощник"></div></div><div class="auth-right"><div class="auth-form"><div class="logo">be</div><h1>С возвращением!</h1><p class="muted" style="margin:0 0 26px">Войди в свой учебный кабинет.</p><form data-form="login"><div><label for="email">Электронная почта</label><input id="email" type="email" name="email" autocomplete="username" required placeholder="student@be.demo"></div><div><label for="password">Пароль</label><input id="password" type="password" name="password" autocomplete="current-password" required placeholder="Пароль"></div><button class="button primary wide" type="submit">Войти ${I('arrow',18)}</button></form>${state.demo?`<div class="section-spacing"><div class="muted small strong">ДЕМО-ДОСТУП ДЛЯ ТЕСТИРОВАНИЯ</div><div class="demo-users"><button class="demo-user" data-action="fill-demo" data-id="student">🎓 Ученик</button><button class="demo-user" data-action="fill-demo" data-id="teacher">📚 Учитель</button><button class="demo-user" data-action="fill-demo" data-id="parent">👨‍👩‍👧 Родитель</button><button class="demo-user" data-action="fill-demo" data-id="admin">⚙️ Администратор</button></div></div><div class="info-note section-spacing">Это тестовый режим с настоящей базой данных на сервере. Для боевого запуска отключи демо-аккаунты и настрой защищённый сервер.</div>`:''}</div></div></div>`}
function courseIcon(color){return {blue:'</>',violet:'∑',mint:'Aa',peach:'⚛',gold:'01'}[color]||'✦'}
function courseCard(c){return `<div class="card item-card hover"><div class="course-visual ${H(c.color)}">${courseIcon(c.color)}</div><div><h3>${H(c.name)}</h3><p class="muted small">${H(c.description)}</p></div><div><div class="row between small" style="margin-bottom:7px"><span>${c.completed}/${c.lesson_count} уроков</span><b>${c.progress}%</b></div><div class="meter"><span style="width:${c.progress}%"></span></div></div><button class="button soft wide" data-action="course" data-id="${c.id}">Открыть предмет ${I('arrow',17)}</button></div>`}
function quickCourse(list){return list.map(c=>`<div class="lesson-card"><div class="badge-circle">${courseIcon(c.color)}</div><div style="flex:1"><div class="row between"><h3>${H(c.name)}</h3><b>${c.progress}%</b></div><p class="small muted">${c.completed} из ${c.lesson_count} уроков</p><div class="meter" style="margin:8px 0"><span style="width:${c.progress}%"></span></div></div><button class="text-link" data-action="course" data-id="${c.id}">${I('arrow')}</button></div>`).join('')}
function quizRow(q){return `<div class="lesson-card"><div class="badge-circle">${I('check')}</div><div style="flex:1"><h3>${H(q.title)}</h3><p class="small muted">${H(q.course)} · ${q.question_count} вопросов · ${q.attempts} попыток</p><div class="row" style="margin-top:7px"><span class="tag">${q.best===null?'Не пройден':'Лучший результат: '+q.best+'%'}</span></div></div><button class="button primary sm" data-action="${state.user.role==='student'?'quiz':'quiz-preview'}" data-id="${q.id}">${state.user.role!=='student'?'Посмотреть':q.attempts?'Повторить':'Начать'}</button></div>`}
async function loadPage(){const role=state.user.role,p=state.page;
 if(p==='dashboard')return role==='student'?studentDashboard():role==='parent'?parentDashboard():staffDashboard();
 if(p==='subjects')return subjectsPage();if(p==='quizzes')return quizzesPage();if(p==='assistant')return assistantPage();if(p==='progress')return progressPage();if(p==='rewards')return rewardsPage();if(p==='schedule')return schedulePage();if(p==='assignments')return assignmentsPage();if(p==='grades')return gradesPage();if(p==='notifications')return notificationsPage();if(p==='settings')return settingsPage();if(p==='gradebook')return gradebookPage();if(p==='work')return workPage();if(p==='administration')return adminPage();}
async function studentDashboard(){const [d,qs,assign]=await Promise.all([api('/overview'),api('/quizzes'),api('/assignments')]);const next=qs.find(q=>q.best===null)||qs[0];const percent=next?.best??0;const soon=assign.filter(x=>!x.submission).slice(0,2);const progress=d.progress.length?d.progress:[{score:0,label:'Старт'}];setPage(`<div class="hero-grid"><section class="card hero"><div class="hero-copy"><span class="tag" style="background:white;color:#5749a6">Бебешка · учебный помощник</span><h2>Сложная тема? Давай разберём её вместе!</h2><p>Объяснения, подсказки и практика — в одном месте.</p><div class="row wrap"><button class="button primary" data-page="assistant">Спросить Бебешку</button><button class="button ghost" data-page="quizzes">Практика</button></div></div><img class="sheep" src="/static/bebeshka.svg" alt="Барашек Бебешка"></section><section class="card blue-card"><div><div class="small strong" style="opacity:.85">Следующая практика</div><h2 style="margin-top:12px">${H(next?.title||'Выбери первый тест')}</h2></div><div class="circle-progress" style="--pct:${percent}"><span>${percent}%</span></div><button class="button ghost wide" ${next?`data-action="quiz" data-id="${next.id}"`:'data-page="quizzes"'}>Начать тест</button></section><section class="card coin-card"><div><div class="coin-icon">🪙</div><div class="strong small" style="margin-top:20px">BEcoin</div><div class="big">${d.balance.coin.toLocaleString('ru-RU')}</div><div class="small">За успехи и старание</div></div><button class="button ghost wide" data-page="rewards">⭐ ${d.balance.star} Stars · Магазин ${I('arrow',16)}</button></section></div><div class="grid main3"><div class="stack"><div class="card"><div class="section-title"><h2>Твой прогресс</h2><span class="tag">Средний балл: ${d.average===null?'—':d.average+'%'}</span></div><p class="muted small">Результаты последних пройденных тестов</p><div class="progress-bars">${progress.map(x=>`<div class="bar" style="height:${Math.max(8,x.score)}%"><span>${H(x.label)}</span></div>`).join('')}</div><div style="height:25px"></div></div><div class="card"><div class="section-title"><h2>Продолжить обучение</h2><button class="text-link" data-page="subjects">Все предметы ${I('arrow',15)}</button></div>${quickCourse(d.courses.slice(0,3))}</div></div><div class="stack"><div class="card"><div class="section-title"><h2>На этой неделе</h2><button class="text-link" data-page="schedule">Расписание</button></div>${d.events.slice(0,3).map(e=>`<div class="lesson-card"><div class="badge-circle">${I('calendar')}</div><div><b>${H(e.title)}</b><p class="muted small">${F(e.when_at)}</p></div></div>`).join('')||'<div class="empty">Нет событий</div>'}</div><div class="card"><div class="section-title"><h2>Задания</h2><button class="text-link" data-page="assignments">Все</button></div>${soon.map(x=>`<div class="lesson-card"><div><b>${H(x.title)}</b><p class="muted small">До ${F(x.due_at)}</p></div></div>`).join('')||'<div class="empty">Все задания сданы 🎉</div>'}</div></div></div>`)}
async function subjectsPage(){const cs=await api('/courses');setPage(`<div class="section-title"><div><h2>Мои предметы</h2><p class="muted">Изучай темы, проходи тесты и отслеживай прогресс.</p></div><span class="tag">${cs.length} предметов</span></div><div class="grid cols3">${cs.map(courseCard).join('')}</div>`)}
async function openCourse(id){state.courseId=id;const d=await api('/courses/'+id);setPage(`<button class="button soft" data-page="subjects">${I('back')} Все предметы</button><div class="section-spacing"><div class="card" style="margin-bottom:22px"><span class="tag">${d.course.progress}% пройдено</span><h1 style="margin:12px 0">${H(d.course.name)}</h1><p class="muted">${H(d.course.description)}</p></div><div class="grid main3"><div><div class="section-title"><h2>Уроки</h2><span class="tag">${d.course.completed}/${d.course.lesson_count}</span></div><div class="card">${d.lessons.map((l,i)=>`<div class="lesson-card"><div class="badge-circle">${l.done?'✓':i+1}</div><div style="flex:1"><h3>${H(l.title)}</h3><p class="muted small">${l.done?'Урок завершён':'Объяснение и практика'}</p></div><button class="button soft sm" data-action="lesson" data-id="${l.id}">Открыть</button></div>`).join('')}</div></div><div><div class="section-title"><h2>Тесты по предмету</h2></div><div class="card">${d.quizzes.map(quizRow).join('')}</div></div></div></div>`);state._lessons=d.lessons;state._course=d.course;
if(['teacher','admin'].includes(state.user.role))document.querySelector('#content').insertAdjacentHTML('afterbegin',`<div class="row wrap" style="margin-bottom:18px"><button class="button primary" data-action="new-lesson" data-id="${id}">${I('plus')} Новый урок</button><button class="button soft" data-action="new-quiz" data-id="${id}">${I('plus')} Создать тест</button></div>`);
}
function openLesson(id){const l=state._lessons?.find(x=>x.id===Number(id));if(!l)return toast('Урок не найден',true);modal(`<h2 style="margin-bottom:15px">${H(l.title)}</h2><div class="detail-panel">${H(l.content)}</div><div class="row between" style="margin-top:20px"><span class="tag">${state.user.role==='student'?(l.done?'✓ Уже пройден':'+20 BEcoin'):'Материал курса'}</span>${state.user.role==='student'?`<button class="button primary" ${l.done?'disabled':''} data-action="finish-lesson" data-id="${id}">${l.done?'Урок завершён':'Отметить как пройденный'}</button>`:''}</div>`)}
async function quizzesPage(){const list=await api('/quizzes');setPage(`<div class="section-title"><div><h2>Проверяй свои знания</h2><p class="muted">${list.length} тестов. Учителя могут добавлять новые тесты. Ответы проверяет сервер.</p></div><span class="tag">${list.filter(x=>x.best!==null).length}/${list.length} пройдено</span></div><div class="grid cols2">${list.map(q=>`<div class="card">${quizRow(q)}</div>`).join('')}</div>`);if(state.user.role!=='student'){document.querySelector('#content').insertAdjacentHTML('afterbegin',`<button class="button primary" data-action="new-quiz" data-id="" style="margin-bottom:16px">${I('plus')} Создать новый тест</button>`)}}
async function openQuiz(id){state.quiz=await api('/quizzes/'+id);state.answers=Array(state.quiz.questions.length).fill(null);state.quizIndex=0;state.result=null;renderQuiz()}
function renderQuiz(){const q=state.quiz;if(!q)return;const i=state.quizIndex,question=q.questions[i];setPage(`<div style="max-width:850px;margin:0 auto"><div class="row between" style="margin-bottom:16px"><button class="button soft" data-page="quizzes">${I('back')} Все тесты</button><span class="tag">Вопрос ${i+1} из ${q.questions.length}</span></div><div class="card"><div class="row between"><div><span class="muted-title">${H(q.course)}</span><h2 style="margin:5px 0 12px">${H(q.title)}</h2></div><div class="badge-circle">${I('check')}</div></div><div class="meter" style="margin-bottom:30px"><span style="width:${(i+1)/q.questions.length*100}%"></span></div><h2 style="margin-bottom:24px">${H(question.prompt)}</h2>${question.options.map((opt,j)=>`<button class="question-option ${state.answers[i]===j?'selected':''}" data-action="answer" data-id="${j}">${String.fromCharCode(65+j)}. ${H(opt)}</button>`).join('')}<div class="row between section-spacing"><button class="button soft" data-action="quiz-prev" ${i===0?'disabled':''}>Назад</button><button class="button primary" data-action="${i===q.questions.length-1?'quiz-submit':'quiz-next'}">${i===q.questions.length-1?'Завершить тест':'Следующий вопрос'} ${I('arrow',17)}</button></div></div></div>`)}
function renderResult(result){const q=state.quiz;setPage(`<div style="max-width:900px;margin:0 auto"><div class="card"><div class="row between"><div><span class="tag">Тест завершён</span><h1 style="margin-top:12px">${result.percent}% — ${result.score}/${result.total}</h1><p class="muted">${H(q.title)}</p></div><div style="font-size:55px">${result.percent>=80?'🎉':'📘'}</div></div><p style="margin-top:12px">${result.earned?`+${result.earned} BEcoin за первое прохождение!`:'Пройденный тест сохранён в твоём аккаунте.'}</p><div class="split-line"></div><h2 style="margin-bottom:15px">Разбор ответов</h2>${result.review.map((r,i)=>`<div class="${r.correct?'result-correct':'result-wrong'}"><b>${i+1}. ${H(r.prompt)} — ${r.correct?'Верно':'Ошибка'}</b><p class="small">Правильный ответ: ${H(q.questions[i].options[r.answer])}</p><p class="small">${H(r.explanation)}</p></div>`).join('')}<div class="row wrap"><button class="button primary" data-action="quiz" data-id="${q.id}">Пройти ещё раз</button><button class="button soft" data-page="quizzes">К остальным тестам</button></div></div></div>`)}
async function assignmentsPage(){const list=await api('/assignments');setPage(`<div class="section-title"><div><h2>Домашние задания</h2><p class="muted">Отправленные ответы сохраняются на сервере и доступны учителю.</p></div><span class="tag">${list.filter(a=>a.submission).length}/${list.length} сданы</span></div><div class="grid cols2">${list.map(a=>`<div class="card item-card"><div class="row between"><span class="tag">${H(a.course)}</span><span class="small muted">${F(a.due_at)}</span></div><h3>${H(a.title)}</h3><p class="muted small">${H(a.instructions)}</p><div class="row between"><span class="pill">${a.submission?(a.submission.status==='graded'?'✓ Проверено':'✓ Отправлено'):'Ожидает ответа'}</span><button class="button primary sm" data-action="submit-assignment" data-id="${a.id}">${a.submission?'Просмотр':'Сдать'}</button></div>${a.submission?.feedback?`<div class="info-note">Комментарий учителя: ${H(a.submission.feedback)}</div>`:''}</div>`).join('')}</div>`);state._assignments=list}
function openAssignment(id){const a=state._assignments.find(x=>x.id===Number(id));if(!a)return;modal(`<h2>${H(a.title)}</h2><p class="muted">${H(a.course)} · до ${F(a.due_at)}</p><div class="detail-panel" style="margin:14px 0">${H(a.instructions)}</div><form data-form="assignment" data-id="${id}"><div><label>Твой ответ</label><textarea name="content" required minlength="3" ${a.submission?.status==='graded'?'readonly':''}>${H(a.submission?.content||'')}</textarea></div>${a.submission?.feedback?`<div class="info-note">Учитель: ${H(a.submission.feedback)}</div>`:''}${a.submission?.status==='graded'?'':'<button type="submit" class="button primary">Сохранить и отправить</button>'}</form>`)}
async function gradesPage(){let sid=state.user.role==='student'?null:state.selectedStudent;if(state.user.role==='parent'&&!sid){let p=await api('/overview');state.selectedStudent=p.children?.[0]?.id;sid=state.selectedStudent}if(!sid&&state.user.role!=='student'){const list=await api('/teacher/students');state.selectedStudent=list[0]?.id;sid=state.selectedStudent}if(!sid&&state.user.role!=='student'){setPage('<div class="empty">Нет доступных учеников</div>');return}const grades=await api('/grades'+(sid?'?student_id='+sid:''));const users=state.user.role==='parent'?(await api('/overview')).children.map(c=>({id:c.id,name:c.name})):state.user.role==='student'?[]:await api('/teacher/students');setPage(`<div class="card"><div class="section-title"><div><h2>Академические оценки</h2><p class="muted">Только реальные опубликованные результаты</p></div>${users.length?`<select aria-label="Ученик" id="student-switch" style="max-width:240px">${users.map(u=>`<option value="${u.id}" ${u.id===sid?'selected':''}>${H(u.name)}</option>`).join('')}</select>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Предмет</th><th>Работа</th><th>Результат</th><th>Отзыв</th><th>Дата</th></tr></thead><tbody>${grades.map(g=>`<tr><td><b>${H(g.course)}</b></td><td>${H(g.label)}</td><td><span class="tag">${g.score}/${g.max_score} · ${g.percent}%</span></td><td>${H(g.feedback)}</td><td>${F(g.date)}</td></tr>`).join('')||'<tr><td colspan="5">Нет оценок</td></tr>'}</tbody></table></div></div>`)}
async function progressPage(){let d;if(state.user.role==='student')d=await api('/overview');else{let p=await api('/overview');if(state.user.role==='parent'){if(!p.children.length){setPage('<div class="empty">Нет привязанных детей</div>');return}state.selectedStudent=state.selectedStudent||p.children[0].id;d=await api('/students/'+state.selectedStudent+'/overview')}else{const s=await api('/teacher/students');if(!s.length){setPage('<div class="empty">Нет учеников</div>');return}state.selectedStudent=state.selectedStudent||s[0].id;d=await api('/students/'+state.selectedStudent+'/overview')}}let attempts=state.user.role==='student'?await api('/attempts'):[];setPage(`<div class="section-title"><h2>Академический прогресс ${H(d.name)}</h2><span class="tag">${d.average===null?'Нет оценок':'Средний результат: '+d.average+'%'}</span></div><div class="grid cols3"><div class="card"><div class="muted small">Пройдено уроков</div><div class="metric">${d.completed_lessons}</div></div><div class="card"><div class="muted small">Попыток тестов</div><div class="metric">${d.attempt_count}</div></div><div class="card"><div class="muted small">Средний результат</div><div class="metric">${d.average===null?'—':d.average+'%'}</div></div></div><div class="grid main3 section-spacing"><div class="card"><h2>Тестовые результаты</h2><p class="muted small">В реальном порядке прохождения</p>${d.progress.length?`<div class="progress-bars" style="margin-bottom:28px">${d.progress.map(x=>`<div class="bar" style="height:${Math.max(8,x.score)}%"><span>${H(x.label)}</span></div>`).join('')}</div>`:'<div class="empty" style="margin-top:16px">Пройди тест, чтобы увидеть график</div>'}</div><div class="card"><h2>Предметы</h2>${quickCourse(d.courses.slice(0,5))}</div></div>${attempts.length?`<div class="card section-spacing"><h2>История тестов</h2><div class="table-wrap"><table class="data-table"><tbody>${attempts.map(a=>`<tr><td>${H(a.quiz)}</td><td>${a.score}/${a.total}</td><td>${a.percent}%</td><td>${F(a.date)}</td></tr>`).join('')}</tbody></table></div></div>`:''}`)}
async function rewardsPage(){const d=await api('/rewards');setPage(`<div class="grid cols2"><div class="card" style="background:#fff0c4"><div class="coin-icon">🪙</div><p class="muted strong">BEcoin</p><div class="metric">${d.balances.coin}</div></div><div class="card" style="background:#ede8ff"><div class="coin-icon">⭐</div><p class="muted strong">Stars</p><div class="metric">${d.balances.star}</div></div></div><div class="section-title section-spacing"><h2>Магазин оформления</h2><span class="tag">Награды не меняют оценки</span></div><div class="grid cols2">${d.catalog.map(r=>`<div class="reward-card"><div class="reward-swatches ${H(r.theme)}"></div><h3>${H(r.title)}</h3><p class="muted small">${H(r.description)}</p><div class="row between"><span class="strong">${r.currency==='coin'?'🪙':'⭐'} ${r.price}</span><button class="button ${r.owned?'soft':'primary'} sm" ${r.owned?'disabled':''} data-action="redeem" data-id="${H(r.code)}">${r.owned?'Приобретено':'Купить'}</button></div></div>`).join('')}</div><div class="card section-spacing"><h2 style="margin-bottom:15px">История операций</h2>${d.history.map(t=>`<div class="lesson-card"><div class="badge-circle">${t.amount>=0?'+':'−'}</div><div style="flex:1"><b>${H(t.reason)}</b><p class="muted small">${F(t.date)}</p></div><b>${t.amount>0?'+':''}${t.amount} ${t.currency==='coin'?'🪙':'⭐'}</b></div>`).join('')}</div>`)}
async function schedulePage(){const events=await api('/events');setPage(`<div class="section-title"><div><h2>Расписание</h2><p class="muted">Занятия и события твоей школы</p></div>${['teacher','admin'].includes(state.user.role)?`<button class="button primary" data-action="event-form">${I('plus')} Добавить</button>`:''}</div><div class="card">${events.map(e=>`<div class="lesson-card"><div class="badge-circle">${I('calendar')}</div><div style="flex:1"><h3>${H(e.title)}</h3><p class="muted small">${F(e.when_at)}</p></div><span class="tag">${H(e.category)}</span></div>`).join('')||'<div class="empty">Событий пока нет</div>'}</div>`)}
async function notificationsPage(){const list=await api('/notifications');setPage(`<div class="section-title"><h2>Уведомления</h2><button class="button soft sm" data-action="read-notifications">Отметить прочитанными</button></div><div class="card">${list.map(n=>`<div class="lesson-card"><div class="badge-circle">${I('bell')}</div><div><b>${H(n.text)}</b><p class="muted small">${F(n.date)}</p></div>${n.read?'':'<span class="tag">Новое</span>'}</div>`).join('')||'<div class="empty">Пока нет уведомлений</div>'}</div>`)}
async function assistantPage(){const enabled=false;setPage(`<div class="grid main3"><div class="card chat"><div class="row"><div class="badge-circle" style="background:#e8dfff">🐑</div><div><h2>Бебешка</h2><p class="muted small">Учебный помощник · ${state.user.demo?'демоверсия':'доступен'}</p></div></div><div class="info-note" style="margin-top:12px">Без API-ключа работает локальный справочник. Для полноценного AI подключается серверный провайдер.</div><div class="chat-messages" id="chat-messages">${state.chat.map(m=>`<div class="bubble ${m.role==='user'?'mine':''}">${H(m.text)}</div>`).join('')}</div><form class="chat-composer" data-form="assistant"><input name="message" aria-label="Вопрос Бебешке" placeholder="Например, объясни циклы Python..." required minlength="2" maxlength="1000"><button class="button primary" title="Отправить">${I('send')}</button></form></div><div class="card" style="align-self:start"><div style="text-align:center"><img src="/static/bebeshka.svg" style="height:190px;max-width:100%" alt="Бебешка"></div><h3>О чём поговорим?</h3><p class="muted small" style="margin:7px 0 16px">Выбери тему или напиши собственный вопрос.</p>${['Объясни цикл for и range(5)','Как решать линейные уравнения?','Помоги понять второй закон Ньютона','Explain Present Simple','Как работает бинарный поиск?'].map(s=>`<button class="question-option" data-action="suggest" data-message="${H(s)}">${H(s)} ${I('arrow',16)}</button>`).join('')}</div></div>`);document.querySelector('#chat-messages')?.scrollTo(0,99999)}
async function settingsPage(){let owned=['sky'];if(state.user.role==='student'){const d=await api('/rewards');owned.push(...d.catalog.filter(r=>r.owned).map(r=>r.theme))}setPage(`<div class="grid main3"><div class="card"><h2>Мой профиль</h2><p class="muted small" style="margin-bottom:24px">Настройки сохраняются в базе данных</p><form data-form="profile"><div><label>Имя</label><input name="name" required minlength="2" value="${H(state.user.name)}"></div><div><label>Язык интерфейса</label><select name="locale">${[['ru','Русский'],['kk','Қазақша'],['en','English']].map(([v,t])=>`<option value="${v}" ${state.user.locale===v?'selected':''}>${t}</option>`).join('')}</select></div><div><label>Тема кабинета</label><select name="theme">${owned.map(v=>`<option value="${H(v)}" ${state.user.theme===v?'selected':''}>${({sky:'Стандартная синяя',mint:'Мятная',violet:'Лавандовая',peach:'Персиковая',night:'Ночная'})[v]}</option>`).join('')}</select></div><button class="button primary" type="submit">Сохранить настройки</button></form></div><div class="card"><h2>Аккаунт</h2><div class="lesson-card"><div class="badge-circle">${I('users')}</div><div><b>${H(state.user.email)}</b><p class="muted small">Роль: ${H(state.user.role)}</p></div></div><div class="lesson-card"><div class="badge-circle">${I('book')}</div><div><b>${H(state.user.school)}</b><p class="muted small">Школа</p></div></div><div class="split-line"></div><h3 style="margin-bottom:14px">Изменить пароль</h3><form data-form="password"><div><label>Текущий пароль</label><input name="current_password" type="password" required></div><div><label>Новый пароль (от 10 символов)</label><input name="new_password" type="password" minlength="10" required></div><button class="button soft">Обновить пароль</button></form><button class="button danger section-spacing" data-action="logout">Выйти из аккаунта</button></div></div>`)}
async function parentDashboard(){const d=await api('/overview');if(!d.children.length){setPage(`<div class="card empty">Дети пока не привязаны к аккаунту. Администратор школы может привязать ребёнка.</div>`);return}state.selectedStudent=state.selectedStudent||d.children[0].id;let st=d.children.find(c=>c.id===state.selectedStudent)||d.children[0];setPage(`<div class="section-title"><h2>Мои дети</h2><span class="tag">${d.children.length} привязано</span></div><div class="row wrap">${d.children.map(c=>`<button class="button ${state.selectedStudent===c.id?'primary':'soft'}" data-action="select-child" data-id="${c.id}">${H(c.name)}</button>`).join('')}</div><div class="grid cols3 section-spacing"><div class="card"><div class="muted small">Средний академический результат</div><div class="metric">${st.overview.average??'—'}%</div></div><div class="card"><div class="muted small">Пройдено уроков</div><div class="metric">${st.overview.completed_lessons}</div></div><div class="card"><div class="muted small">Тестовых попыток</div><div class="metric">${st.overview.attempt_count}</div></div></div><div class="grid main3 section-spacing"><div class="card"><div class="section-title"><h2>Последние оценки ${H(st.name)}</h2><button class="text-link" data-page="grades">Все оценки</button></div>${st.overview.grades.map(g=>`<div class="lesson-card"><div class="badge-circle">${I('chart')}</div><div style="flex:1"><b>${H(g.course)}</b><p class="muted small">${H(g.label)}</p></div><span class="tag">${g.percent}%</span></div>`).join('')||'<div class="empty">Оценок нет</div>'}</div><div class="card"><h2>Прогресс по предметам</h2>${quickCourse(st.overview.courses)}</div></div>`)}
async function staffDashboard(){const d=await api('/overview');setPage(`<div class="hero-grid"><div class="card hero"><div class="hero-copy"><span class="tag">${state.user.role==='admin'?'Администрирование':'Панель учителя'}</span><h2>Организуй обучение в одном месте.</h2><p>Оценки, задания и результаты учеников теперь связаны с общей базой.</p><div class="row wrap"><button class="button primary" data-page="${state.user.role==='admin'?'administration':'gradebook'}">${state.user.role==='admin'?'Пользователи':'Выставить оценку'}</button><button class="button ghost" data-page="work">Проверить работы</button></div></div><img class="sheep" src="/static/bebeshka.svg" alt="Бебешка"></div><div class="card blue-card"><div><div class="small">Ваши классы</div><h2>${d.courses.length} предметов</h2></div><div class="metric">${d.students.length}</div><p>учеников</p><button class="button ghost" data-page="gradebook">Открыть журнал</button></div><div class="card coin-card"><div><div style="font-size:35px">🗂️</div><div style="margin-top:22px" class="small">Ожидают проверки</div><div class="big">${d.pending_submissions}</div></div><button class="button ghost" data-page="work">Проверить задания ${I('arrow',16)}</button></div></div><div class="grid main3"><div class="card"><div class="section-title"><h2>Предметы и классы</h2><button class="text-link" data-page="subjects">Все</button></div>${d.courses.map(c=>`<div class="lesson-card"><div class="badge-circle">${courseIcon(c.color)}</div><div style="flex:1"><h3>${H(c.name)}</h3><p class="muted small">${c.lesson_count} уроков · ${c.quiz_count} тестов</p></div></div>`).join('')||'<div class="empty">Предметы пока не назначены</div>'}</div><div class="card"><h2>Быстрые действия</h2><div class="stack section-spacing"><button class="button soft wide" data-page="gradebook">${I('plus')} Поставить оценку</button><button class="button soft wide" data-page="work">${I('check')} Создать задание</button><button class="button soft wide" data-page="schedule">${I('calendar')} Добавить занятие</button>${state.user.role==='admin'?`<button class="button soft wide" data-page="administration">${I('users')} Создать аккаунт</button>`:''}</div></div></div>`)}
async function gradebookPage(){const [courses,students]=await Promise.all([api('/courses'),api('/teacher/students')]);state._staffCourses=courses;state._staffStudents=students;setPage(`<div class="section-title"><div><h2>Электронный журнал</h2><p class="muted">Выставленная оценка сразу появится в кабинете нужного ученика.</p></div><span class="tag">${students.length} учеников</span></div><div class="grid main3"><div class="card"><h2 style="margin-bottom:18px">Новая оценка</h2>${courses.length&&students.length?`<form data-form="grade"><div><label>Ученик</label><select name="student_id" required>${students.map(s=>`<option value="${s.id}">${H(s.name)}</option>`).join('')}</select></div><div><label>Предмет</label><select name="course_id" required>${courses.map(c=>`<option value="${c.id}">${H(c.name)}</option>`).join('')}</select></div><div><label>Название работы</label><input name="label" value="Проверочная работа" required minlength="2"></div><div class="grid cols2"><div><label>Баллы</label><input name="score" type="number" min="0" step="0.1" required value="85"></div><div><label>Максимум</label><input name="max_score" type="number" min="1" step="0.1" required value="100"></div></div><div><label>Комментарий</label><textarea name="feedback" placeholder="Что было хорошо и что улучшить?"></textarea></div><button class="button primary">Опубликовать оценку</button></form>`:'<div class="empty">Сначала нужны курс и хотя бы один ученик.</div>'}</div><div class="card"><h2>Ученики</h2>${students.map(s=>`<div class="lesson-card"><div class="badge-circle">${I('users')}</div><div style="flex:1"><b>${H(s.name)}</b><p class="muted small">ID ${s.id}</p></div><button class="text-link" data-action="staff-grades" data-id="${s.id}">Оценки</button></div>`).join('')}</div></div>`)}
async function workPage(){const [courses,rows]=await Promise.all([api('/courses'),api('/teacher/submissions')]);state._submissions=rows;setPage(`<div class="section-title"><div><h2>Задания и проверка работ</h2><p class="muted">Создавай задания и оценивай отправленные ответы.</p></div><span class="tag">${rows.filter(r=>r.status==='submitted').length} ожидают проверки</span></div><div class="grid main3"><div class="card"><h2 style="margin-bottom:15px">Работы учеников</h2>${rows.map(r=>`<div class="lesson-card"><div class="badge-circle">${I('check')}</div><div style="flex:1"><b>${H(r.student)}</b><p class="muted small">${H(r.title)} · ${H(r.course)}</p><span class="tag">${r.status==='graded'?'Проверено':'Ждёт оценки'}</span></div><button class="button soft sm" data-action="review" data-id="${r.id}">Открыть</button></div>`).join('')||'<div class="empty">Пока нет отправленных работ</div>'}</div><div class="card"><h2 style="margin-bottom:16px">Создать задание</h2><form data-form="new-assignment"><div><label>Предмет</label><select name="course_id" required>${courses.map(c=>`<option value="${c.id}">${H(c.name)}</option>`).join('')}</select></div><div><label>Название</label><input name="title" required minlength="3" placeholder="Решить задачи"></div><div><label>Описание</label><textarea name="instructions" required minlength="5" placeholder="Инструкции ученикам"></textarea></div><div><label>Срок сдачи</label><input name="due_at" type="datetime-local" required value="${new Date(Date.now()+86400000*5).toISOString().slice(0,16)}"></div><button class="button primary" ${courses.length?'':'disabled'}>Опубликовать</button></form></div></div><div class="card section-spacing"><h2 style="margin-bottom:12px">Объявление ученикам</h2><form data-form="announcement"><div><label>Предмет и класс</label><select name="course_id">${courses.map(c=>`<option value="${c.id}">${H(c.name)}</option>`).join('')}</select></div><div><label>Сообщение</label><textarea name="text" minlength="5" maxlength="250" required placeholder="Урок завтра в 15:00…"></textarea></div><button class="button primary">Отправить уведомление</button></form></div>`)}
function openReview(id){const r=state._submissions.find(x=>x.id===Number(id));if(!r)return;modal(`<h2>${H(r.student)} — ${H(r.title)}</h2><p class="muted small">${H(r.course)}</p><div class="detail-panel section-spacing">${H(r.content)}</div>${r.status==='graded'?`<div class="info-note section-spacing">Оценка: ${r.score}/100. ${H(r.feedback)}</div>`:`<form data-form="review" data-id="${id}" style="margin-top:18px"><div><label>Оценка (0–100)</label><input name="score" type="number" min="0" max="100" required value="85"></div><div><label>Комментарий</label><textarea name="feedback" required minlength="2">Хорошая работа!</textarea></div><button class="button primary">Проверить и поставить оценку</button></form>`}`)}
async function adminPage(){const [users,classes]=await Promise.all([api('/admin/users'),api('/admin/classes')]);setPage(`<div class="section-title"><div><h2>Управление школой</h2><p class="muted">Новые аккаунты создаются на сервере, а не только в интерфейсе.</p></div><span class="tag">${users.length} аккаунтов</span></div><div class="grid main3"><div class="card"><h2 style="margin-bottom:15px">Пользователи</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Имя</th><th>Email</th><th>Роль</th></tr></thead><tbody>${users.map(u=>`<tr><td>${u.id}</td><td>${H(u.name)}</td><td>${H(u.email)}</td><td>${H(u.role)}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2 style="margin-bottom:17px">Создать аккаунт</h2><form data-form="new-user"><div><label>Имя</label><input name="name" minlength="2" required></div><div><label>Email</label><input name="email" type="email" required></div><div><label>Пароль (от 10 символов)</label><input name="password" type="password" minlength="10" required></div><div><label>Роль</label><select name="role"><option value="student">Ученик</option><option value="teacher">Учитель</option><option value="parent">Родитель</option></select></div><div><label>Класс (для ученика)</label><select name="classroom_id"><option value="">Не выбран</option>${classes.map(c=>`<option value="${c.id}">${H(c.name)}</option>`).join('')}</select></div><button class="button primary">Создать пользователя</button></form></div></div><div class="card section-spacing"><h2 style="margin-bottom:15px">Связать родителя с учеником</h2><form data-form="parent-link" class="grid cols3"><div><label>Родитель</label><select name="parent_id">${users.filter(x=>x.role==='parent').map(u=>`<option value="${u.id}">${H(u.name)} (${u.id})</option>`).join('')}</select></div><div><label>Ученик</label><select name="student_id">${users.filter(x=>x.role==='student').map(u=>`<option value="${u.id}">${H(u.name)} (${u.id})</option>`).join('')}</select></div><button class="button primary" type="submit" style="align-self:end">Привязать</button></form></div>`);extraAdminControls(users,classes);adminSchoolForm()}
function adminSchoolForm(){document.querySelector('#content').insertAdjacentHTML('beforeend',`<div class="card section-spacing"><h2 style="margin-bottom:12px">Название школы</h2><form data-form="school"><div><label>Название</label><input name="name" value="${H(state.user.school)}" minlength="3" required></div><button class="button soft">Сохранить название</button></form></div>`)}
async function eventForm(){const cs=await api('/admin/classes');modal(`<h2 style="margin-bottom:18px">Новое событие</h2><form data-form="new-event"><div><label>Класс</label><select name="classroom_id">${cs.map(x=>`<option value="${x.id}">${H(x.name)}</option>`).join('')}</select></div><div><label>Название</label><input name="title" minlength="3" required placeholder="Урок Python"></div><div><label>Дата и время</label><input type="datetime-local" name="when_at" required value="${new Date(Date.now()+86400000).toISOString().slice(0,16)}"></div><div><label>Тип</label><select name="category"><option value="lesson">Занятие</option><option value="test">Тест</option><option value="event">Мероприятие</option></select></div><button class="button primary">Добавить в расписание</button></form>`)}
async function sendMessage(text){const msg=(text||'').trim();if(msg.length<2)return;state.chat.push({role:'user',text:msg});state.chat.push({role:'bot',text:'Думаю над объяснением…'});assistantPage();try{const d=await api('/assistant','POST',{message:msg});state.chat[state.chat.length-1]={role:'bot',text:d.reply+(d.mode==='guide'?'\n\n(Ответ из учебного справочника)':'')};}catch(e){state.chat[state.chat.length-1]={role:'bot',text:'Не удалось получить ответ: '+e.message}}assistantPage()}

function quizPreview(id){api('/quizzes/'+id).then(d=>modal(`<h2>${H(d.title)}</h2><p class="muted small">Предпросмотр теста · ${d.question_count} вопросов</p>${d.questions.map((q,i)=>`<div class="detail-panel" style="margin-top:12px"><b>${i+1}. ${H(q.prompt)}</b><p>${q.options.map((o,j)=>`${String.fromCharCode(65+j)}. ${H(o)}`).join('<br>')}</p></div>`).join('')}`)).catch(e=>toast(e.message,true))}
function newLessonForm(id){modal(`<h2 style="margin-bottom:14px">Добавить урок</h2><form data-form="new-lesson" data-id="${id}"><div><label>Название</label><input name="title" minlength="3" maxlength="150" required placeholder="Новая тема"></div><div><label>Текст урока</label><textarea name="content" required minlength="10" rows="8" placeholder="Объяснение, пример и практика…"></textarea></div><button class="button primary">Создать урок</button></form>`)}
function quizQuestion(index){return `<div class="detail-panel quiz-question-builder" style="margin-top:12px"><b>Вопрос ${index+1}</b><div style="margin-top:12px"><label>Формулировка</label><input name="prompt" required minlength="4" placeholder="Что выведет этот код?"></div><div class="grid cols2" style="margin-top:12px">${[0,1,2,3].map(i=>`<div><label>Вариант ${String.fromCharCode(65+i)}</label><input name="opt${i}" required placeholder="Ответ"></div>`).join('')}</div><div style="margin-top:12px"><label>Правильный вариант</label><select name="answer"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></div><div style="margin-top:12px"><label>Объяснение ответа</label><input name="explanation" minlength="3" required placeholder="Почему это правильный ответ?"></div></div>`}
async function newQuizForm(courseId){const courses=await api('/courses');if(!courses.length){toast('Сначала создайте предмет',true);return}modal(`<h2>Создать тест</h2><p class="muted small">Вопросы и ответы сохраняются в базе данных. Правильные варианты скрыты от ученика до сдачи.</p><form data-form="new-quiz" style="margin-top:15px"><div><label>Предмет</label><select name="course_id">${courses.map(c=>`<option value="${c.id}" ${String(c.id)===String(courseId)?'selected':''}>${H(c.name)}</option>`).join('')}</select></div><div><label>Название теста</label><input name="title" required minlength="4" placeholder="Тест №1: Логика"></div><div id="quiz-question-list">${[0,1,2].map(quizQuestion).join('')}</div><button type="button" data-action="add-quiz-question" class="button soft">${I('plus')} Добавить вопрос</button><button type="submit" class="button primary">Опубликовать тест</button></form>`)}
function extraAdminControls(users,classes){const teachers=users.filter(u=>u.role==='teacher');document.querySelector('#content').insertAdjacentHTML('beforeend',`<div class="grid cols2 section-spacing"><div class="card"><h2 style="margin-bottom:16px">Создать класс</h2><form data-form="new-class"><div><label>Название класса</label><input name="name" required minlength="2" placeholder="9А"></div><button class="button primary">Добавить класс</button></form></div><div class="card"><h2 style="margin-bottom:16px">Создать предмет</h2>${teachers.length&&classes.length?`<form data-form="new-course"><div><label>Название</label><input name="name" required minlength="2" placeholder="Биология"></div><div><label>Описание</label><input name="description" placeholder="Темы и практика"></div><div><label>Класс</label><select name="classroom_id">${classes.map(c=>`<option value="${c.id}">${H(c.name)}</option>`).join('')}</select></div><div><label>Учитель</label><select name="teacher_id">${teachers.map(t=>`<option value="${t.id}">${H(t.name)}</option>`).join('')}</select></div><div><label>Цвет курса</label><select name="color"><option value="blue">Синий</option><option value="violet">Фиолетовый</option><option value="mint">Мятный</option><option value="peach">Персиковый</option><option value="gold">Золотой</option></select></div><button class="button primary">Создать предмет</button></form>`:'<div class="info-note">Для создания предмета сначала нужен учитель и класс.</div>'}</div></div>`)}

// All clickable controls are delegated here and use real API operations.
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');if(nav){closeModal();go(nav.dataset.page);return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='close'){closeModal();return}if(a==='mobile-menu'){modal(`<h2 style="margin-bottom:16px">Все разделы</h2><div class="grid cols2">${menuItems().map(p=>`<button class="button soft" data-page="${p}">${I(ICONS[p])} ${tr(p)}</button>`).join('')}</div>`);return}if(a==='retry'){go(state.page);return}if(a==='logout'){await api('/logout','POST',{});state.user=null;closeModal();renderLogin();toast('Вы вышли');return}
 if(a==='fill-demo'){document.querySelector('#email').value=id+'@be.demo';document.querySelector('#password').value='Demo123!';toast('Демо-аккаунт выбран — нажми «Войти»');return}
 if(a==='course'){await openCourse(id);return}if(a==='lesson'){openLesson(id);return}
 if(a==='finish-lesson'){let d=await api('/lessons/'+id+'/complete','POST',{});closeModal();toast(d.earned?'Урок завершён! +'+d.earned+' BEcoin':'Этот урок уже пройден');await openCourse(state.courseId);return}
 if(a==='quiz'){await openQuiz(id);return}if(a==='quiz-preview'){quizPreview(id);return}if(a==='new-lesson'){newLessonForm(id);return}if(a==='new-quiz'){await newQuizForm(id);return}if(a==='add-quiz-question'){const box=document.querySelector('#quiz-question-list');if(box.querySelectorAll('.quiz-question-builder').length>=30){toast('Максимум 30 вопросов',true);return}box.insertAdjacentHTML('beforeend',quizQuestion(box.querySelectorAll('.quiz-question-builder').length));return}if(a==='answer'){state.answers[state.quizIndex]=Number(id);renderQuiz();return}if(a==='quiz-prev'){state.quizIndex=Math.max(0,state.quizIndex-1);renderQuiz();return}if(a==='quiz-next'){state.quizIndex=Math.min(state.quiz.questions.length-1,state.quizIndex+1);renderQuiz();return}if(a==='quiz-submit'){el.disabled=true;const result=await api('/quizzes/'+state.quiz.id+'/submit','POST',{answers:state.answers});state.result=result;renderResult(result);toast('Тест сохранён: '+result.percent+'%');return}
 if(a==='submit-assignment'){openAssignment(id);return}if(a==='redeem'){if(!confirm('Купить награду за баллы?'))return;await api('/rewards/'+id+'/redeem','POST',{});toast('Награда куплена! Открой Настройки, чтобы применить тему.');await rewardsPage();return}
 if(a==='read-notifications'){await api('/notifications/read','POST',{});toast('Прочитано');await notificationsPage();return}if(a==='suggest'){await sendMessage(el.dataset.message);return}
 if(a==='select-child'){state.selectedStudent=Number(id);await parentDashboard();return}if(a==='staff-grades'){state.selectedStudent=Number(id);go('grades');return}
 if(a==='review'){openReview(id);return}if(a==='event-form'){await eventForm();return}
 }catch(err){toast(err.message,true);el.disabled=false}});
document.addEventListener('change',e=>{if(e.target.id==='student-switch'){state.selectedStudent=Number(e.target.value);gradesPage().catch(err=>toast(err.message,true))}});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form,data=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type=submit],button:not([type])');if(submit)submit.disabled=true;try{
 if(type==='login'){await api('/login','POST',data);state.user=await api('/me');go('dashboard');toast('Добро пожаловать!');return}
 if(type==='assignment'){const d=await api('/assignments/'+form.dataset.id+'/submit','POST',{content:data.content});closeModal();toast('Работа отправлена учителю'+(d.earned?' · +'+d.earned+' BEcoin':''));await assignmentsPage();return}
 if(type==='profile'){await api('/me','PATCH',data);state.user=await api('/me');toast('Настройки сохранены');go('settings');return}
 if(type==='assistant'){form.reset();await sendMessage(data.message);return}
 if(type==='grade'){await api('/teacher/grades','POST',{...data,student_id:Number(data.student_id),course_id:Number(data.course_id),score:Number(data.score),max_score:Number(data.max_score)});toast('Оценка опубликована');go('gradebook');return}
 if(type==='new-assignment'){await api('/teacher/assignments','POST',{...data,course_id:Number(data.course_id)});toast('Задание опубликовано');go('work');return}
 if(type==='review'){await api('/teacher/submissions/'+form.dataset.id+'/review','POST',{score:Number(data.score),feedback:data.feedback});closeModal();toast('Работа проверена, оценка сохранена');go('work');return}
 if(type==='new-event'){await api('/teacher/events','POST',{...data,classroom_id:Number(data.classroom_id)});closeModal();toast('Событие добавлено');go('schedule');return}
 if(type==='password'){await api('/me/password','POST',data);form.reset();toast('Пароль изменён');return}
 if(type==='announcement'){await api('/teacher/announcements','POST',{course_id:Number(data.course_id),text:data.text});toast('Уведомление отправлено');go('work');return}
 if(type==='school'){await api('/admin/school','PATCH',data);state.user=await api('/me');toast('Название школы обновлено');go('administration');return}
 if(type==='new-class'){await api('/admin/classes','POST',data);toast('Класс создан');go('administration');return}
 if(type==='new-course'){await api('/admin/courses','POST',{...data,teacher_id:Number(data.teacher_id),classroom_id:Number(data.classroom_id)});toast('Предмет создан');go('administration');return}
 if(type==='new-lesson'){await api('/teacher/lessons','POST',{...data,course_id:Number(form.dataset.id)});closeModal();toast('Урок опубликован');await openCourse(form.dataset.id);return}
 if(type==='new-quiz'){const sections=[...form.querySelectorAll('.quiz-question-builder')];const questions=sections.map(el=>({prompt:el.querySelector('[name=prompt]').value,options:[0,1,2,3].map(i=>el.querySelector(`[name=opt${i}]`).value),answer:Number(el.querySelector('[name=answer]').value),explanation:el.querySelector('[name=explanation]').value}));await api('/teacher/quizzes','POST',{course_id:Number(data.course_id),title:data.title,questions});closeModal();toast('Тест опубликован');go('quizzes');return}
 if(type==='new-user'){await api('/admin/users','POST',{...data,classroom_id:data.classroom_id?Number(data.classroom_id):null});toast('Аккаунт создан');go('administration');return}
 if(type==='parent-link'){await api('/admin/parent-link','POST',{parent_id:Number(data.parent_id),student_id:Number(data.student_id)});toast('Связь сохранена');go('administration');return}
 }catch(err){toast(err.message,true)}finally{if(submit)submit.disabled=false}});
start();
